public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryRejectInvalidContext(principal, resource, request, out var decision))
            return decision;

        if (TryRejectInvalidState(principal!, resource!, request!, out decision))
            return decision;

        var access = GetAccessFacts(principal!, resource!, request!, delegations);

        if (TryHandleBreakGlass(request!, access.Administrator, out decision))
            return decision;

        if (TryRejectRestrictedAccess(resource!, request!, out decision))
            return decision;

        if (TryRejectUnauthorizedAction(request!, access, out decision))
            return decision;

        var outsideBusinessHours = request!.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            access.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource!.Classification == "restricted");
    }

    private static bool TryRejectInvalidContext(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
            return Reject("missing-context", true, out decision);

        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Reject("invalid-identity", true, out decision);

        decision = default!;
        return false;
    }

    private static bool TryRejectInvalidState(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (principal.Suspended)
            return Reject("principal-suspended", true, out decision);

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Reject("tenant-mismatch", true, out decision);

        if (resource.Locked && request.Action != "read")
            return Reject("resource-locked", true, out decision);

        if (request.MinuteOfDay is < 0 or > 1439)
            return Reject("invalid-time", true, out decision);

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Reject("challenge-required", true, out decision);

        decision = default!;
        return false;
    }

    private static AccessFacts GetAccessFacts(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AccessFacts(administrator, operatorRole, auditor, owner, delegated);
    }

    private static bool TryHandleBreakGlass(
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (!request.BreakGlass)
        {
            decision = default!;
            return false;
        }

        decision = !administrator || !request.StrongAuthentication
            ? new AccessDecision(false, "invalid-break-glass", true)
            : new AccessDecision(true, "break-glass", true);
        return true;
    }

    private static bool TryRejectRestrictedAccess(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Reject("strong-authentication-required", true, out decision);

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Reject("trusted-network-required", true, out decision);

        decision = default!;
        return false;
    }

    private static bool TryRejectUnauthorizedAction(
        AccessRequest request,
        AccessFacts access,
        out AccessDecision decision)
    {
        switch (request.Action)
        {
            case "delete":
                return RejectUnless(access.Administrator, "administrator-required", true, out decision);
            case "write":
                return RejectUnless(CanWrite(access), "write-not-authorised", true, out decision);
            case "read":
                return RejectUnless(CanRead(access), "read-not-authorised", false, out decision);
            default:
                return Reject("unknown-action", true, out decision);
        }
    }

    private static bool CanWrite(AccessFacts access) =>
        access.Administrator || access.Operator || access.Owner || access.Delegated;

    private static bool CanRead(AccessFacts access) =>
        access.Administrator || access.Operator || access.Auditor || access.Owner || access.Delegated;

    private static bool RejectUnless(
        bool authorized,
        string reason,
        bool requiresAudit,
        out AccessDecision decision)
    {
        if (!authorized)
            return Reject(reason, requiresAudit, out decision);

        decision = default!;
        return false;
    }

    private static bool Reject(string reason, bool requiresAudit, out AccessDecision decision)
    {
        decision = new AccessDecision(false, reason, requiresAudit);
        return true;
    }

    private readonly record struct AccessFacts(
        bool Administrator,
        bool Operator,
        bool Auditor,
        bool Owner,
        bool Delegated);
}
